  addToast: (msg: string, type: 'success' | 'error') => void;
}

type JobType = 'Full-time' | 'Part-time' | 'Contract' | 'Consultancy';
type JobStatus = 'Draft' | 'Open' | 'Closed';

interface FormData {
  job_code: string;
  status: JobStatus;
  client: string;
  job_type: JobType;
  job_duration: string;
