import { WEBHOOK_CONFIG } from '../config';

const TOKEN_KEY = 'token';
const USER_KEY = 'user';

/**
 * Helper to retrieve tenant_id from local storage or JWT fallback.
 * Uses real runtime values, never n8n expressions.
 */
export function getTenantId(): string | null {
  try {
    const userStr = localStorage.getItem(USER_KEY);
    const user = userStr ? JSON.parse(userStr) : null;

    // 1. Check stored user object for tenant_id
    if (user?.tenant_id) return user.tenant_id;

    // 2. Fallback: decode JWT payload
    const token = localStorage.getItem(TOKEN_KEY);
    if (!token) return null;

    try {
      // Decode JWT payload (base64url)
      const payloadPart = token.split(".")[1];
      if (!payloadPart) return null;

      const payload = JSON.parse(atob(payloadPart.replace(/-/g, '+').replace(/_/g, '/')));
      return payload.tenant_id || null;
    } catch {
      return null;
    }
  } catch (error) {
    console.error("Error retrieving tenant_id:", error);
    return null;
  }
}

async function handleResponse(response: Response) {
  if (response.status === 401 || response.status === 403) {
    console.warn('Session expired or unauthorized. Clearing storage.');
    localStorage.removeItem(TOKEN_KEY);
    localStorage.removeItem(USER_KEY);
    localStorage.removeItem('cv_analyzer_auth');

    window.location.reload();
    return new Promise(() => {});
  }

  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    throw new Error(errorData.message || `API Error: ${response.status} ${response.statusText}`);
  }
  return response.json();
}

export const apiService = {
  async post(url: string, data: any, token?: string) {
    const headers: HeadersInit = {
      'Content-Type': 'application/json',
    };

    // Read real token from storage, never use {{ }}
    const activeToken = token || localStorage.getItem(TOKEN_KEY);
    if (activeToken) {
      headers['Authorization'] = `Bearer ${activeToken}`;
    }

    const response = await fetch(url, {
      method: 'POST',
      headers,
      body: JSON.stringify(data),
    });
    return handleResponse(response);
  },

  async get(url: string, params: Record<string, string> = {}, token?: string) {
    const headers: HeadersInit = {
      'Content-Type': 'application/json',
    };

    const activeToken = token || localStorage.getItem(TOKEN_KEY);
    if (activeToken) {
      headers['Authorization'] = `Bearer ${activeToken}`;
    }

    const queryString = new URLSearchParams(params).toString();
    const fullUrl = queryString ? `${url}?${queryString}` : url;

    const response = await fetch(fullUrl, {
      method: 'GET',
      headers,
    });
    return handleResponse(response);
  }
};

