import React, { useState, useEffect } from 'react';
import { apiService } from '../services/api';
import { WEBHOOK_CONFIG, GLOBAL_FORWARDING_EMAIL } from '../config';
import { User } from '../types';

interface AddJobModalProps {
  onClose: () => void;
  onSuccess: () => void;
  token: string;
  user: User | null;
  addToast: (msg: string, type: 'success' | 'error') => void;
}

type JobType = 'Full-time' | 'Part-time' | 'Contract' | 'Consultancy';
type JobStatus = 'Draft' | 'Open' | 'Closed';

interface FormData {
  job_code: string;
  status: JobStatus;
  client: string;
  job_type: JobType;
  job_duration: string;
  job_location: string;
  job_title: string;
  job_description: string;
  other_information: string;
  end_date: string;
}

export const AddJobModal: React.FC<AddJobModalProps> = ({ onClose, onSuccess, token, user, addToast }) => {
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState<FormData>({
    job_code: '',
    status: 'Open',
    client: '',
    job_type: 'Full-time',
    job_duration: '',
    job_location: '',
    job_title: '',
    job_description: '',
    other_information: '',
    end_date: ''
  });

  // Debug log to verify user context and ingestion mode
  useEffect(() => {
    console.log("AddJobModal mounted. User context:", user);
    console.log("Current Ingestion Mode:", user?.cv_ingestion_mode);
  }, [user]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    console.log("CREATE JOB SUBMIT CLICKED");

    try {
      console.log("SUBMIT START");

      const token = localStorage.getItem("token");
      if (!token) {
        alert("Not authenticated. Please login again.");
        return;
      }

      if (!formData.job_code || !formData.job_type || !formData.job_title || !formData.job_description) {
        addToast("Please fill in all required fields.", "error");
        return;
      }

      setLoading(true);

      const res = await fetch(WEBHOOK_CONFIG.CREATE_JOB_WEBHOOK_URL, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "authorization": `Bearer ${token}`
        },
        body: JSON.stringify({
          job_code: formData.job_code,
          status: formData.status,
          client: formData.client || null,
          job_type: formData.job_type,
          job_duration: formData.job_duration || null,
          job_location: formData.job_location || null,
          job_title: formData.job_title,
          job_description: formData.job_description,
          other_information: formData.other_information || null,
          end_date: formData.end_date || null
        })
      });

      const text = await res.text();
      console.log("RESPONSE STATUS:", res.status);

      if (!res.ok) {
        throw new Error(`Server responded with ${res.status}: ${text}`);
      }

      addToast("Job campaign created successfully!", "success");
      onSuccess();
    } catch (err: any) {
      console.error("SUBMIT ERROR", err);
      alert(err.message || "Submit failed");
      addToast(err.message || "Failed to create job.", "error");
    } finally {
      setLoading(false);
    }
  };

  const isFormValid = formData.job_code && formData.job_type && formData.job_title && formData.job_description;

  // Normalized mode for case-insensitive comparison
  const normalizedMode = user?.cv_ingestion_mode?.toLowerCase();

  return (
    <div className="fixed inset-0 bg-textMain/60 backdrop-blur-sm z-50 flex items-center justify-center p-4 overflow-y-auto">
