import React, { useState, useEffect } from 'react';
import { AuthState, User, ApplicationFilter } from './types';
import { AuthPage } from './pages/Auth';
import { Layout } from './components/Layout';
import { JobsDashboard } from './pages/JobsDashboard';
import { JobDetails } from './pages/JobDetails';
import { ApplicationsList } from './pages/ApplicationsList';
import { AddJobModal } from './components/AddJobModal';
import { ToastContainer, ToastType } from './components/Toast';

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<string>('jobs');
  const [selectedJobCode, setSelectedJobCode] = useState<string | null>(null);
  const [appFilter, setAppFilter] = useState<ApplicationFilter>('all');
  const [isAddJobOpen, setIsAddJobOpen] = useState(false);

  // Auth State - initialized from individual localStorage keys
  const [auth, setAuth] = useState<AuthState>(() => {
    try {
      const token = localStorage.getItem('token');
      const userStr = localStorage.getItem('user');
      const user = userStr ? JSON.parse(userStr) : null;
      return { token, user };
    } catch (e) {
      return { token: null, user: null };
    }
  });

  const [toasts, setToasts] = useState<{ id: number; message: string; type: ToastType }[]>([]);

  const addToast = (message: string, type: ToastType) => {
    const id = Date.now();
    setToasts((prev) => [...prev, { id, message, type }]);
  };

  const removeToast = (id: number) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
  };

  // Sync state to storage
  useEffect(() => {
    if (auth.token && auth.user) {
      localStorage.setItem('token', auth.token);
      localStorage.setItem('user', JSON.stringify(auth.user));
    } else {
      localStorage.removeItem('token');
      localStorage.removeItem('user');
    }
  }, [auth]);

  const handleLoginSuccess = (token: string, user: User) => {
    setAuth({ token, user });
    addToast("Welcome back!", "success");
  };

  const handleLogout = () => {
    setAuth({ token: null, user: null });
    setCurrentPage('jobs');
    setSelectedJobCode(null);
    addToast("Logged out successfully", "info");
  };

  if (!auth.token) {
    return (
      <div className="min-h-screen bg-slate-50">
        <AuthPage onLoginSuccess={handleLoginSuccess} addToast={addToast} />
        <ToastContainer toasts={toasts} removeToast={removeToast} />
      </div>
    );
  }

  const renderContent = () => {
    switch (currentPage) {
      case 'jobs':
        return (
          <JobsDashboard 
            auth={auth} 
            onViewDetails={(code) => {
              setSelectedJobCode(code);
              setCurrentPage('job-details');
            }}
            onViewApplications={(code, filter) => {
              setSelectedJobCode(code);
              setAppFilter(filter as ApplicationFilter);
              setCurrentPage('applications');
            }}
            onAddJob={() => setIsAddJobOpen(true)}
            addToast={addToast}
          />
        );
      case 'job-details':
        if (!selectedJobCode) {
          setCurrentPage('jobs');
          return null;
        }
        return (
          <JobDetails 
            jobId={selectedJobCode!} // Updated prop name to jobId
            auth={auth} 
            onBack={() => setCurrentPage('jobs')}
            addToast={addToast}
          />
        );
      case 'applications':
        if (!selectedJobCode) {
          setCurrentPage('jobs');
          return null;
        }
        return (
          <ApplicationsList 
            jobCode={selectedJobCode!} 
            initialFilter={appFilter}
            auth={auth} 
            onBack={() => setCurrentPage('jobs')}
            addToast={addToast}
          />
        );
      default:
        return (
          <div className="flex flex-col items-center justify-center h-full py-12 text-center">
            <h3 className="text-lg font-medium text-textMain">Page not found</h3>
            <button 
              onClick={() => setCurrentPage('jobs')}
              className="mt-4 text-primary hover:underline"
            >
              Return to dashboard
            </button>
          </div>
        );
    }
  };

  return (
    <div className="min-h-screen bg-background">
      <Layout 
        user={auth.user} 
        onLogout={handleLogout} 
        currentPage={currentPage} 
        onNavigate={setCurrentPage}
      >
        {renderContent()}
      </Layout>

      {isAddJobOpen && (
        <AddJobModal 
          onClose={() => setIsAddJobOpen(false)} 
          onSuccess={(jobId) => {
            setIsAddJobOpen(false);
            setSelectedJobCode(jobId);
            setCurrentPage('job-details');
            console.log(`Job created successfully. Redirecting to job-details for: ${jobId}`);
          }}
          user={auth.user}
          token={auth.token!}
          addToast={addToast}
        />
      )}

      <ToastContainer toasts={toasts} removeToast={removeToast} />
    </div>
  );
};

export default App;

