import React, { useState, useEffect } from 'react';
import { AuthState, User, ApplicationFilter } from './types';
import { AuthPage } from './pages/Auth';
import { Layout } from './components/Layout';
import { JobsDashboard } from './pages/JobsDashboard';
import { JobDetails } from './pages/JobDetails';
import { ApplicationsList } from './pages/ApplicationsList';
import { AddJobModal } from './components/AddJobModal';
import { ToastContainer, ToastType } from './components/Toast';

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<string>('jobs');
  const [selectedJobId, setSelectedJobId] = useState<string | null>(null);
  const [appFilter, setAppFilter] = useState<ApplicationFilter>('all');
  const [isAddJobOpen, setIsAddJobOpen] = useState(false);

  // Auth State - initialized from individual localStorage keys
  const [auth, setAuth] = useState<AuthState>(() => {
    try {
      const token = localStorage.getItem('token');
      const userStr = localStorage.getItem('user');
      const user = userStr ? JSON.parse(userStr) : null;
      return { token, user };
    } catch (e) {
      return { token: null, user: null };
    }
  });

  const [toasts, setToasts] = useState<{ id: number; message: string; type: ToastType }[]>([]);

  const addToast = (message: string, type: ToastType) => {
    const id = Date.now();
    setToasts((prev) => [...prev, { id, message, type }]);
  };

  const removeToast = (id: number) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
  };

  // Sync state to storage
  useEffect(() => {
    if (auth.token && auth.user) {
      localStorage.setItem('token', auth.token);
      localStorage.setItem('user', JSON.stringify(auth.user));
    } else {
      localStorage.removeItem('token');
      localStorage.removeItem('user');
    }
  }, [auth]);

  const handleLoginSuccess = (token: string, user: User) => {
    setAuth({ token, user });
    addToast("Welcome back!", "success");
  };

  const handleLogout = () => {
    setAuth({ token: null, user: null });
    setCurrentPage('jobs');
    setSelectedJobId(null);
    addToast("Logged out successfully", "info");
  };

  const handleViewApplications = (id: string, filter: string) => {
    console.log(`[App] Navigating to applications. ID (UUID): ${id}, Filter: ${filter}`);
    setSelectedJobId(id);
    setAppFilter(filter as ApplicationFilter);
    setCurrentPage('applications');
  };

  if (!auth.token) {
    return (
      <div className="min-h-screen bg-slate-50">
        <AuthPage onLoginSuccess={handleLoginSuccess} addToast={addToast} />
        <ToastContainer toasts={toasts} removeToast={removeToast} />
      </div>
    );
  }

  const renderContent = () => {
    switch (currentPage) {
      case 'jobs':
        return (
          <JobsDashboard 
            auth={auth} 
            onViewDetails={(id) => {
              console.log(`[App] Navigating to job-details. ID (UUID): ${id}`);
              setSelectedJobId(id);
              setCurrentPage('job-details');
            }}
            onViewApplications={handleViewApplications}
            onAddJob={() => setIsAddJobOpen(true)}
            addToast={addToast}
          />
        );
      case 'job-details':
        if (!selectedJobId) {
          setCurrentPage('jobs');
          return null;
        }
        return (
          <JobDetails 
            jobId={selectedJobId!} 
            auth={auth} 
            onBack={() => setCurrentPage('jobs')}
            onViewApplications={handleViewApplications}
            addToast={addToast}
          />
        );
      case 'applications':
        if (!selectedJobId) {
          setCurrentPage('jobs');
          return null;
        }
        return (
          <ApplicationsList 
            jobId={selectedJobId!} 
            initialFilter={appFilter}
            auth={auth} 
            onBack={() => setCurrentPage('jobs')}
            addToast={addToast}
          />
        );
      default:
        return (
          <div className="flex flex-col items-center justify-center h-full py-12 text-center">
            <h3 className="text-lg font-medium text-textMain">Page not found</h3>
            <button 
              onClick={() => setCurrentPage('jobs')}
              className="mt-4 text-primary hover:underline"
            >
              Return to dashboard
            </button>
          </div>
        );
    }
  };

  return (
    <div className="min-h-screen bg-background">
      <Layout 
        user={auth.user} 
        onLogout={handleLogout} 
        currentPage={currentPage} 
        onNavigate={setCurrentPage}
      >
        {renderContent()}
      </Layout>

      {isAddJobOpen && (
        <AddJobModal 
          onClose={() => setIsAddJobOpen(false)} 
          onSuccess={(jobId) => {
            console.log(`[App] Job created successfully. ID (UUID): ${jobId}`);
            setIsAddJobOpen(false);
            setSelectedJobId(jobId);
            setCurrentPage('job-details');
          }}
          user={auth.user}
          token={auth.token!}
          addToast={addToast}
        />
      )}

      <ToastContainer toasts={toasts} removeToast={removeToast} />
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { apiService } from '../services/api';
import { WEBHOOK_CONFIG } from '../config';
import { User } from '../types';
import { ToastType } from '../components/Toast';

interface AuthPageProps {
  onLoginSuccess: (token: string, user: User) => void;
  addToast: (msg: string, type: ToastType) => void;
}

export const AuthPage: React.FC<AuthPageProps> = ({ onLoginSuccess, addToast }) => {
  const [activeTab, setActiveTab] = useState<'login' | 'register'>('login');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [showLoginPassword, setShowLoginPassword] = useState(false);
  const [showRegisterPassword, setShowRegisterPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  const [loginForm, setLoginForm] = useState({ email: '', password: '' });

  const [registerForm, setRegisterForm] = useState({
    company_name: '',
    admin_name: '',
    admin_email: '',
    password: '',
    confirm_password: '',
    cv_ingestion_mode: 'platform_email' as 'platform_email' | 'forwarding',
    forward_email: ''
  });

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    try {
      const response = await apiService.post(WEBHOOK_CONFIG.LOGIN_WEBHOOK_URL, loginForm);

      if (response && response.token) {
        const userData: User = {
          ...response.user,
          email: response.user?.email || loginForm.email,
          cv_ingestion_mode: response.cv_ingestion_mode || response.user?.cv_ingestion_mode
        };
        onLoginSuccess(response.token, userData);
      } else {
        throw new Error("Missing authentication token.");
      }
    } catch (err: any) {
      // Catch specific backend error message from apiService
      const errorMsg = err.message || "Unable to sign in.";
      setError(errorMsg);
      addToast(errorMsg, "error");
    } finally {
      setLoading(false);
    }
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    if (registerForm.password !== registerForm.confirm_password) {
      setError("Passwords do not match");
      return;
    }

    setLoading(true);
    try {
      // Explicit payload construction as per backend expectations
      const payload: any = {
        company_name: registerForm.company_name,
        admin_email: registerForm.admin_email,
        admin_name: registerForm.admin_name,
        password: registerForm.password,
        confirm_password: registerForm.confirm_password,
        intake_mode: registerForm.cv_ingestion_mode
      };

      // Conditionally include forward_email if mode is forwarding
      if (registerForm.cv_ingestion_mode === 'forwarding') {
        payload.forward_email = registerForm.forward_email;
      }

      await apiService.post(WEBHOOK_CONFIG.REGISTER_WEBHOOK_URL, payload);
      addToast("Registration successful!", "success");
      setActiveTab('login');
    } catch (err: any) {
      setError(err.message || "Registration failed.");
      addToast(err.message || "Registration failed.", "error");
    } finally {
      setLoading(false);
    }
  };

  const PasswordToggle = ({ isVisible, onToggle, label }: { isVisible: boolean, onToggle: () => void, label: string }) => (
    <button
      type="button"
      onClick={onToggle}
      aria-label={isVisible ? `Hide ${label}` : `Show ${label}`}
      className="absolute right-3 top-1/2 -translate-y-1/2 text-textMuted hover:text-primary transition-colors focus:outline-none"
    >
      {isVisible ? (
        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-5 h-5">
          <path strokeLinecap="round" strokeLinejoin="round" d="M3.98 8.223A10.477 10.477 0 001.934 12C3.226 16.338 7.244 19.5 12 19.5c.993 0 1.953-.138 2.863-.395M6.228 6.228A10.45 10.45 0 0112 4.5c4.756 0 8.773 3.162 10.065 7.498a10.523 10.523 0 01-4.293 5.774M6.228 6.228L3 3m3.228 3.228l3.65 3.65m7.894 7.894L21 21m-3.228-3.228l-3.65-3.65m0 0a3 3 0 10-4.243-4.243m4.242 4.242L9.88 9.88" />
        </svg>
      ) : (
        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-5 h-5">
          <path strokeLinecap="round" strokeLinejoin="round" d="M2.036 12.322a1.012 1.012 0 010-.644C3.399 8.049 7.21 5 12 5c4.79 0 8.601 3.049 9.964 6.678.14.373.14.76 0 1.134C20.601 15.951 16.79 19 12 19c-4.79 0-8.601-3.049-9.964-6.678z" />
          <path strokeLinecap="round" strokeLinejoin="round" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
        </svg>
      )}
    </button>
  );

  return (
    <div className="flex flex-col items-center justify-center min-h-screen p-4 bg-slate-50">
      <div className="mb-8 text-center">
        <h1 className="text-3xl font-bold text-primary mb-2 tracking-tight">CV Analyzer</h1>
        <p className="text-textMuted max-w-xs mx-auto">Enterprise resume analysis and hiring intelligence.</p>
      </div>

      <div className="bg-white w-full max-w-md rounded-2xl shadow-xl border border-border overflow-hidden">
        <div className="flex border-b border-border bg-slate-50">
          <button
            onClick={() => { setActiveTab('login'); setError(null); }}
            className={`flex-1 py-4 text-xs font-bold uppercase tracking-widest transition-all ${
              activeTab === 'login' ? 'bg-white text-primary border-b-2 border-primary' : 'text-textMuted'
            }`}
          >
            Sign In
          </button>
          <button
            onClick={() => { setActiveTab('register'); setError(null); }}
            className={`flex-1 py-4 text-xs font-bold uppercase tracking-widest transition-all ${
              activeTab === 'register' ? 'bg-white text-primary border-b-2 border-primary' : 'text-textMuted'
            }`}
          >
            Register
          </button>
        </div>

        <div className="p-8">
          {error && (
            <div className="mb-6 p-4 bg-red-50 border-l-4 border-error text-error text-sm rounded flex items-start">
              <svg className="w-5 h-5 mr-3 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
              <span>{error}</span>
            </div>
          )}

          {activeTab === 'login' ? (
            <form onSubmit={handleLogin} className="space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-textMuted uppercase tracking-widest">Work Email</label>
                <input
                  required
                  type="email"
                  disabled={loading}
                  className="w-full px-4 py-3 border border-border rounded-xl outline-none focus:border-primary transition-all"
                  placeholder="name@company.com"
                  value={loginForm.email}
                  onChange={(e) => setLoginForm({...loginForm, email: e.target.value})}
                />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-textMuted uppercase tracking-widest">Password</label>
                <div className="relative">
                  <input
                    required
                    type={showLoginPassword ? "text" : "password"}
                    disabled={loading}
                    className="w-full pl-4 pr-12 py-3 border border-border rounded-xl outline-none focus:border-primary transition-all"
                    placeholder="••••••••"
                    value={loginForm.password}
                    onChange={(e) => setLoginForm({...loginForm, password: e.target.value})}
                  />
                  <PasswordToggle 
                    isVisible={showLoginPassword} 
                    onToggle={() => setShowLoginPassword(!showLoginPassword)} 
                    label="password" 
                  />
                </div>
              </div>
              <button
                type="submit"
                disabled={loading}
                className="w-full bg-primary hover:bg-primaryDark text-white py-3 rounded-xl font-bold shadow-lg shadow-primary/20 transition-all flex items-center justify-center"
              >
                {loading ? "Signing in..." : "Sign In"}
              </button>
            </form>
          ) : (
            <form onSubmit={handleRegister} className="space-y-4">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-textMuted uppercase tracking-widest">Company Name</label>
                <input
                  required
