          { label: 'Total Applications', value: stats?.total_applications, color: 'text-success', icon: '📄' },
          { label: 'Ingest Failures (24h)', value: stats?.failed_ingest_24h, color: stats?.failed_ingest_24h ? 'text-error' : 'text-textMuted', icon: '⚠️' }
